const $=s=>document.querySelector(s);let state={coins:350,wins:0,frogName:'Näckros',personality:null,bond:0,careLog:{},adventures:{},decorOwned:['flowers'],decorSlots:['flowers','none','none'],cup:null,cupWins:0,trust:0,royalRaces:0,royalWins:0,visitedTracks:[],claimedQuests:[],name:'Dagg',gender:'Kvinnlig',skin:'#efc6a1',hair:'#784c39',outfit:'#b68bc2',frog:'#88ad55',owned:[],hatched:false,eggClicks:0,hairstyle:'long',eyeShape:'round',mouth:'smile',headwear:'leaf',pattern:'plain',baseStats:[45,55,40]};try{const s=JSON.parse(localStorage.getItem('grodgaloppen'));if(s&&Number.isFinite(s.coins)&&Array.isArray(s.owned))state={...state,...s}}catch{}if(!state.personality){state.personality=['Modig','Sömnig','Busig'][Math.floor(Math.random()*3)];save()}let tab='race',chosen=0,running=false;const items=[{id:'goggles',name:'Racingglasögon',icon:'🥽',desc:'Klar sikt, snabba språng.',cost:150,stat:0,bonus:22},{id:'boots',name:'Studsstövlar',icon:'👢',desc:'Lite extra studs över varje rot.',cost:180,stat:1,bonus:25},{id:'charm',name:'Daggamulett',icon:'💎',desc:'Skogens energi, hela vägen i mål.',cost:200,stat:2,bonus:25},{id:'scarf',name:'Vindhalsduk',icon:'🧣',desc:'Fånga vinden på din nästa tävling.',cost:120,stat:0,bonus:13}];function save(){if(typeof syncFrogs==='function')syncFrogs();try{localStorage.setItem('grodgaloppen',JSON.stringify(state))}catch{toast('Webbläsaren kunde inte spara framstegen.')}}function stats(){const a=[...state.baseStats];items.forEach(i=>{if(state.owned.includes(i.id))a[i.stat]+=i.bonus});return a}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
// The team portrait. Shading (fgShade) and skin texture (fgDots) are drawn as overlays in white and
// dark green, so they work on any frog colour. Shared <defs> ids are identical in every copy.
const frogDefs=`<defs><radialGradient id="fgShade" cx=".38" cy=".28" r=".85"><stop offset="0" stop-color="#fff" stop-opacity=".42"/><stop offset=".42" stop-color="#fff" stop-opacity="0"/><stop offset=".78" stop-color="#14240f" stop-opacity=".12"/><stop offset="1" stop-color="#14240f" stop-opacity=".38"/></radialGradient><radialGradient id="fgGround" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="#22351f" stop-opacity=".42"/><stop offset=".6" stop-color="#22351f" stop-opacity=".18"/><stop offset="1" stop-color="#22351f" stop-opacity="0"/></radialGradient><pattern id="fgDots" width="16" height="13" patternUnits="userSpaceOnUse" patternTransform="rotate(12)"><circle cx="3" cy="3" r="1.5" fill="#14240f" opacity=".16"/><circle cx="11" cy="9" r="1.1" fill="#fff" opacity=".22"/><circle cx="13" cy="2" r=".8" fill="#14240f" opacity=".12"/></pattern><radialGradient id="fgSkin" cx=".42" cy=".34" r=".8"><stop offset="0" stop-color="#fff" stop-opacity=".3"/><stop offset=".55" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#6b3324" stop-opacity=".28"/></radialGradient><linearGradient id="fgCloth" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".28"/><stop offset=".5" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".22"/></linearGradient><linearGradient id="fgWing" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".85"/><stop offset=".55" stop-color="#fff" stop-opacity=".15"/><stop offset="1" stop-color="#b9a4d6" stop-opacity=".35"/></linearGradient><radialGradient id="fgBelly"><stop offset="0" stop-color="#f3f8cf" stop-opacity=".75"/><stop offset=".7" stop-color="#f3f8cf" stop-opacity=".35"/><stop offset="1" stop-color="#f3f8cf" stop-opacity="0"/></radialGradient><radialGradient id="fgEye" cx=".4" cy=".3" r=".8"><stop offset="0" stop-color="#fff"/><stop offset=".7" stop-color="#f7f1c9"/><stop offset="1" stop-color="#d9cf9a"/></radialGradient></defs>`;
function frog(color=state.frog,player=true){
 const edge='stroke="#14240f" stroke-opacity=".18" stroke-width="2"';
 const fairy=player?`${typeof wingShape==='function'?wingShape():'<g stroke="#fff6ec" stroke-width="2"><ellipse cx="137" cy="80" rx="19" ry="43" transform="rotate(-40 137 80)" fill="#f5e6fb" opacity=".8"/><ellipse cx="167" cy="78" rx="16" ry="39" transform="rotate(35 167 78)" fill="#e3f0f6" opacity=".8"/></g>'}${typeof outfitShape==='function'?outfitShape():`<path d="M148 112 Q137 130 125 147 L157 153 165 113" fill="${state.outfit}"/>`}<path d="M148 112Q137 130 125 147L157 153 165 113Z" fill="url(#fgCloth)"/><path d="M151 118Q145 133 137 148M158 118Q158 134 151 151" stroke="#000" stroke-opacity=".16" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M146 134 L161 154 181 157" fill="none" stroke="${state.skin}" stroke-width="9" stroke-linecap="round"/><path d="M147 137 L161 157 180 160" fill="none" stroke="#6b3324" stroke-opacity=".16" stroke-width="3" stroke-linecap="round"/><path d="M159 112 L178 131 195 129" fill="none" stroke="${state.skin}" stroke-width="7" stroke-linecap="round"/><path d="M160 115 L178 134 194 132" fill="none" stroke="#6b3324" stroke-opacity=".15" stroke-width="2.5" stroke-linecap="round"/><circle cx="182" cy="157" r="5" fill="${state.skin}"/><circle cx="196" cy="129" r="4.2" fill="${state.skin}"/><path d="M133 83 Q130 51 152 53 Q178 54 169 91" fill="${state.hair}"/><path d="M137 84Q135 62 150 58" stroke="#000" stroke-opacity=".18" stroke-width="3" fill="none" stroke-linecap="round"/><ellipse cx="153" cy="99" rx="8" ry="3" fill="#6b3324" opacity=".22"/><ellipse cx="153" cy="80" rx="16" ry="20" fill="${state.skin}"/><ellipse cx="153" cy="80" rx="16" ry="20" fill="url(#fgSkin)"/><g fill="#e8808a" opacity=".38"><circle cx="145" cy="88" r="3.6"/><circle cx="162" cy="88" r="3.6"/></g><path d="M155.5 84.5q1.6 1.8 -.4 3" stroke="#a46b4f" stroke-opacity=".55" stroke-width="1.2" fill="none" stroke-linecap="round"/><path d="M136 74 Q147 78 151 62 Q165 63 170 77 Q172 51 150 54 Q132 55 136 74" fill="${state.hair}"/><path d="M141 62Q150 55 163 60M146 68Q151 62 156 61" stroke="#fff" stroke-opacity=".3" stroke-width="2.4" fill="none" stroke-linecap="round"/>${hairShape()}${eyeShape()}${mouthShape()}${headwearShape()}`:'';
 const body=`<path d="M68 200 Q47 214 27 207 M86 204 Q74 220 58 213 M163 200 Q181 218 213 208" fill="none" stroke="#14240f" stroke-opacity=".2" stroke-width="16" stroke-linecap="round"/><path d="M68 200 Q47 214 27 207 M86 204 Q74 220 58 213 M163 200 Q181 218 213 208" fill="none" stroke="${color}" stroke-width="13" stroke-linecap="round"/><g fill="${color}" ${edge}>${[[24,206],[57,213],[214,207]].map(([x,y])=>`<circle cx="${x-5}" cy="${y-3}" r="4"/><circle cx="${x-6}" cy="${y+4}" r="4"/><circle cx="${x+1}" cy="${y+7}" r="4"/>`).join('')}</g><ellipse cx="135" cy="178" rx="76" ry="36" fill="${color}" ${edge}/><ellipse cx="84" cy="188" rx="36" ry="25" fill="${color}"/><ellipse cx="135" cy="178" rx="76" ry="36" fill="url(#fgShade)"/><path d="M52 200Q66 214 98 211" stroke="#14240f" stroke-opacity=".16" stroke-width="3" fill="none" stroke-linecap="round"/><path d="M62 176Q80 166 104 174" stroke="#fff" stroke-opacity=".22" stroke-width="3" fill="none" stroke-linecap="round"/><ellipse cx="135" cy="174" rx="72" ry="31" fill="url(#fgDots)"/><g fill="#14240f" opacity=".1"><ellipse cx="112" cy="160" rx="11" ry="6"/><ellipse cx="148" cy="152" rx="8" ry="4.5"/><ellipse cx="88" cy="176" rx="7" ry="4"/><ellipse cx="74" cy="190" rx="6" ry="4"/></g>${player?'<ellipse cx="150" cy="148" rx="24" ry="6" fill="#14240f" opacity=".16"/>':''}<ellipse cx="194" cy="160" rx="50" ry="34" fill="${color}" stroke="#14240f" stroke-opacity=".1" stroke-width="2"/><ellipse cx="194" cy="160" rx="50" ry="34" fill="url(#fgShade)"/><ellipse cx="196" cy="158" rx="44" ry="28" fill="url(#fgDots)"/>`;
 const face=`${player&&typeof frogHatArt==='function'?frogHatArt():''}<ellipse cx="190" cy="141" rx="17" ry="23" fill="${color}" ${edge}/><ellipse cx="222" cy="143" rx="14" ry="20" fill="${color}" ${edge}/><ellipse cx="190" cy="141" rx="17" ry="23" fill="url(#fgShade)"/><ellipse cx="222" cy="143" rx="14" ry="20" fill="url(#fgShade)"/><ellipse cx="194" cy="140" rx="10" ry="14" fill="url(#fgEye)"/><ellipse cx="224" cy="141" rx="8" ry="12" fill="url(#fgEye)"/><ellipse cx="197" cy="141" rx="4" ry="8" fill="#293f2d"/><ellipse cx="226" cy="142" rx="3" ry="7" fill="#293f2d"/><g fill="#fff"><circle cx="199" cy="136" r="2.2"/><circle cx="196" cy="146" r="1"/><circle cx="228" cy="137" r="1.8"/><circle cx="225" cy="146" r=".8"/></g><path d="M184 128Q194 124 203 130M216 131Q224 127 231 133" stroke="#14240f" stroke-opacity=".22" stroke-width="2" fill="none" stroke-linecap="round"/><g fill="#14240f" opacity=".45"><ellipse cx="228" cy="156" rx="1.7" ry="1.1"/><ellipse cx="236" cy="154.5" rx="1.6" ry="1"/></g><path d="M181 169 Q208 188 235 165" fill="none" stroke="#46603a" stroke-width="3" stroke-linecap="round"/><path d="M181 169q-3-2-4 1M235 165q3-2 4 1" stroke="#46603a" stroke-width="2" fill="none" stroke-linecap="round"/><ellipse cx="178" cy="165" rx="9" ry="5" fill="#e0a07a" opacity=".45"/><ellipse cx="142" cy="190" rx="46" ry="16" fill="url(#fgBelly)"/><ellipse cx="142" cy="193" rx="38" ry="9" fill="#14240f" opacity=".05"/>`;
 return `<svg viewBox="0 0 280 240" xmlns="http://www.w3.org/2000/svg">${frogDefs}<ellipse cx="142" cy="214" rx="118" ry="16" fill="url(#fgGround)"/>${fairy}${body}${face}${player?patternShape():''}${player&&state.owned.includes('goggles')?'<g fill="#b6e4eaa0" stroke="#725a39" stroke-width="5"><rect x="180" y="129" width="28" height="25" rx="9"/><rect x="213" y="130" width="25" height="24" rx="8"/><path d="M207 141h6"/></g><g fill="#fff" opacity=".55"><path d="M186 133l6-2 2 5-6 2Z"/><path d="M219 134l5-2 2 4-5 2Z"/></g>':''}${player&&state.owned.includes('scarf')?'<path d="M170 180 Q148 183 130 172 L105 185 141 190 166 189" fill="#d98769"/><path d="M130 176L150 184M118 182L138 188" stroke="#000" stroke-opacity=".15" stroke-width="2"/>':''}${player&&typeof frogStageArt==='function'?frogStageArt():''}${player&&typeof frogWearArt==='function'?frogWearArt():''}</svg>`}
function scene(){return `<svg viewBox="0 0 900 340" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="bg" x2="0" y2="1"><stop stop-color="#e8edcb"/><stop offset="1" stop-color="#a8c5a0"/></linearGradient></defs><rect width="900" height="340" fill="url(#bg)"/><circle cx="671" cy="77" r="58" fill="#f7efb7" opacity=".7"/><path d="M0 175 Q110 90 220 169 T450 151 T710 130 T950 150V340H0" fill="#b0c293"/><path d="M0 233 Q170 150 320 215 T650 196 T950 206V340H0" fill="#83a97c"/><path d="M0 278 Q260 191 450 245 Q650 287 900 215V340H0" fill="#aacbb4"/><g fill="none" stroke="#e1ecce" opacity=".6"><ellipse cx="560" cy="300" rx="210" ry="16"/><ellipse cx="725" cy="248" rx="87" ry="8"/></g><g fill="#648a58"><path d="M438 293 Q510 257 583 289 Q530 320 438 293L500 289Z"/><path d="M715 300 Q765 270 824 298 Q772 322 715 300L770 297Z"/><path d="M325 260 Q355 242 398 259 Q365 275 325 260Z"/></g><g stroke="#5e8152" stroke-width="5"><path d="M860 340Q835 227 853 160M875 340Q901 230 884 194M32 340Q48 264 23 225"/></g><g fill="#826c43"><rect x="846" y="143" width="13" height="55" rx="6"/><rect x="879" y="179" width="12" height="49" rx="6"/></g><g fill="#f6e9a8"><circle cx="380" cy="111" r="3"/><circle cx="731" cy="160" r="3"/><circle cx="469" cy="73" r="3"/></g><g transform="translate(380 35) scale(1.1)">${frog().replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g fill="#efc8cb"><ellipse cx="752" cy="287" rx="6" ry="16" transform="rotate(-30 752 287)"/><ellipse cx="765" cy="286" rx="6" ry="16" transform="rotate(25 765 286)"/></g></svg>`}
function sidebar(){$('#coins').textContent=state.coins;$('#wins').textContent=state.wins+' segrar';$('#teamName').textContent=state.name+' & '+state.frogName;$('#portrait').innerHTML=frog();$('#stats').innerHTML=stats().map((n,i)=>`<div class="stat"><span>${['Fart','Hopp','Uthållighet'][i]}</span><div class="bar"><i style="width:${n}%"></i></div><span>${n}</span></div>`).join('');$('#royalTrust').innerHTML=trustMeter()}
// Five menu groups; each group has small tabs inside it. The old tab names stay the same everywhere else.
const navGroups=[{id:'race',tabs:[['race','Lopp'],['cup','Mästerskap']]},{id:'team',tabs:[['care','Grodvän'],['frog','Utrustning'],['fairy','Älvan']]},{id:'adventure',tabs:[['adventure','Äventyr'],['astrid','Astrid'],['queen','Besöket',()=>typeof queenVisiting==='function'&&queenVisiting()],['castle','Slottet']]},{id:'home',tabs:[['home','Gläntan'],['house','Svamphuset'],['fish','Fiska'],['fireflies','Eldflugor',()=>typeof unlocked!=='function'||unlocked('fireflies')]]},{id:'village',tabs:[['village','Älvbyn'],['shop','Butiken']]}];
const groupOf=t=>navGroups.find(g=>g.tabs.some(([k])=>k===t))||navGroups[0];const lastTabInGroup={};
function renderSubNav(){const box=$('#subNav');if(!box)return;const g=groupOf(tab);lastTabInGroup[g.id]=tab;const shown=g.tabs.filter(t=>!t[2]||t[2]()||t[0]===tab);if(shown.length<2){box.hidden=true;box.innerHTML='';return}box.hidden=false;box.innerHTML=shown.map(([k,n])=>`<button role="tab" data-subtab="${k}" aria-selected="${k===tab}">${n}</button>`).join('');{const sel=box.querySelector?.('[aria-selected="true"]');if(sel&&box.scrollWidth>box.clientWidth)box.scrollLeft=sel.offsetLeft-(box.clientWidth-sel.offsetWidth)/2}if(box.querySelectorAll)box.querySelectorAll('[data-subtab]').forEach(b=>b.onclick=()=>{if(running){toast('Avsluta loppet eller äventyret först – heja ditt team!');return}tab=b.dataset.subtab;render()})}
function goToGroup(id){const g=navGroups.find(g=>g.id===id)||navGroups[0];const last=g.tabs.find(t=>t[0]===lastTabInGroup[g.id]);tab=last&&(!last[2]||last[2]())?last[0]:g.tabs[0][0];render()}
const musicForTab={race:'meadow',frog:'meadow',fairy:'meadow',care:'glade',astrid:'castle',adventure:'adventure',cup:'castle',home:'glade',fish:'glade',house:'glade',shop:'village',queen:'castle',castle:'emerald',fireflies:'night',village:'village'};
function render(){document.body.classList.toggle('gardenView',['home','village'].includes(tab)&&state.hatched);setMusic(!state.hatched?'meadow':['home','fish'].includes(tab)&&state.garden?.night?'night':musicForTab[tab]||'meadow');if(!state.hatched){renderEgg();return}if(typeof ensureFrogs==='function')ensureFrogs();if(typeof checkUnlocks==='function')checkUnlocks();if(typeof applySeason==='function')applySeason();document.body.classList.remove('hatching');sidebar();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.group===groupOf(tab).id));renderSubNav();if(document.body.dataset)document.body.dataset.tab=tab;const activeNav=document.querySelector('nav button.active');if(activeNav?.scrollIntoView)activeNav.scrollIntoView({inline:'center',block:'nearest'});const c=$('#content');if(tab==='adventure'){renderAdventures();return}if(tab==='care'){renderCare();return}if(tab==='home'){renderHome();return}if(tab==='fish'&&typeof renderFishing==='function'){renderFishing();return}if(tab==='house'&&typeof renderHouse==='function'){renderHouse();return}if(tab==='shop'&&typeof renderShop==='function'){renderShop();return}if(tab==='queen'&&typeof renderQueen==='function'){renderQueen();return}if(tab==='castle'&&typeof renderCastle==='function'){renderCastle();return}if(tab==='fireflies'&&typeof renderFireflies==='function'){renderFireflies();return}if(tab==='village'){renderVillage();return}if(tab==='cup'){renderCup();return}if(tab==='astrid'){renderAstrid();return}if(tab==='race'){renderRaceTab(c)}else if(tab==='frog'){c.innerHTML=`<div class="sectionHead"><h2>${escapeText(genitive(state.frogName))} utrustningsbod</h2><span class="pill">Alla bonusar är aktiva</span></div><p class="statGuide"><strong>Fart</strong> gör det gröna hoppfältet bredare · <strong>Hopp</strong> ger längre skutt · <strong>Uthållighet</strong> gör att du tappar mindre fart vid en miss</p><div class="shop">${items.map(i=>`<article class="card"><div class="icon">${i.icon}</div><h3>${i.name}</h3><p>${i.desc}<br>+${i.bonus} ${['fart','hopp','uthållighet'][i.stat]}</p><button class="primary" data-buy="${i.id}" ${state.owned.includes(i.id)||state.coins<i.cost?'disabled':''}>${state.owned.includes(i.id)?'✓ Utrustad':'✦ '+i.cost+' · Köp'}</button></article>`).join('')}</div><div class="editor" style="margin-top:18px"><h3>En groda i din färg</h3><div class="options">${(typeof frogColorChoices==='function'?frogColorChoices():['#88ad55','#66aaa0','#c49b57','#9c8db5']).map(v=>`<button aria-label="Grodfärg ${v}" class="swatch ${state.frog===v?'chosen':''}" style="background:${v}" data-frog="${v}"></button>`).join('')}</div></div>${typeof wardrobeHTML==='function'?wardrobeHTML([['frogHat','Hatt'],['frogJewel','Smycke']],escapeText(genitive(state.frogName))+' garderob'):''}`;if(typeof wireWardrobe==='function')wireWardrobe(render);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const i=items.find(i=>i.id===b.dataset.buy);if(!state.owned.includes(i.id)&&state.coins>=i.cost){state.coins-=i.cost;state.owned.push(i.id);save();render();toast(i.name+' är nu utrustade!')}});document.querySelectorAll('[data-frog]').forEach(b=>b.onclick=()=>{state.frog=b.dataset.frog;save();render()})}else{c.innerHTML=`<div class="sectionHead"><h2>Din älva, din stil</h2><span class="pill">Alla stilar är gratis</span></div><div class="editor"><div style="height:190px;text-align:center">${frog()}</div><label for="name">Älvans namn</label><input type="text" id="name" maxlength="18"><label>Frisyr</label><div class="options hairstyles">${[['short','Kort'],['long','Långt'],['curly','Lockigt'],['braid','Fläta']].map(([v,n])=>`<button data-style="${v}" aria-pressed="${state.hairstyle===v}" class="${state.hairstyle===v?'chosen':''}">${n}</button>`).join('')}</div><label>Ögonform</label><div class="options hairstyles">${[['round','Runda'],['almond','Mandelformade'],['happy','Glatt slutna']].map(([v,n])=>`<button data-eyes="${v}" aria-pressed="${state.eyeShape===v}" class="${state.eyeShape===v?'chosen':''}">${n}</button>`).join('')}</div>${[['mouth','Muntyp',[['smile','Leende'],['big','Stort leende'],['straight','Liten rak mun'],['surprised','Förvånad']]],['headwear','Huvudbonad',[['none','Ingen'],...(state.cupWins>0?[['champion','Astrids mästarkrans']]:[]),['flowers','Blomsterkrans'],['crown','Krona'],['leaf','Lövhatt'],['mushroom','Svamphatt']]]].map(([key,label,choices])=>`<label>${label}</label><div class="options hairstyles">${choices.map(([v,n])=>`<button data-feature="${key}" data-choice="${v}" aria-pressed="${state[key]===v}" class="${state[key]===v?'chosen':''}">${n}</button>`).join('')}</div>`).join('')}<label>Älvans utseende</label><div class="options">${['Kvinnlig','Manlig'].map(v=>`<button data-gender="${v}" class="${state.gender===v?'chosen':''}">${v} älva</button>`).join('')}</div>${[['skin','Hudfärg',['#f7dfcc','#efc6a1','#d6a077','#b77b55','#89563d','#57382c']],['hair','Hårfärg',['#784c39','#e5c681','#333638','#ce795e','#211c1a','#4b3026','#a57449','#c79351','#ece1bd','#a5a29d','#e5e3de']],['outfit','Klädfärg',['#b68bc2','#79a7c0','#d99783','#789d61']]].map(([key,label,colors])=>`<label>${label}</label><div class="options">${colors.map(v=>`<button aria-label="${label} ${v}" aria-pressed="${state[key]===v}" data-key="${key}" data-color="${v}" class="swatch ${state[key]===v?'chosen':''}" style="background:${v}"></button>`).join('')}</div>`).join('')}<p>✧ Din stil sparas automatiskt och följer med ut på banan.</p></div>${typeof wardrobeHTML==='function'?wardrobeHTML([['wings','Vingar'],['outfitStyle','Kläder']],'Älvans garderob'):''}`;if(typeof wireWardrobe==='function')wireWardrobe(render);document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{state.hairstyle=b.dataset.style;save();render()});document.querySelectorAll('[data-eyes]').forEach(b=>b.onclick=()=>{state.eyeShape=b.dataset.eyes;save();render()});document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>{state[b.dataset.feature]=b.dataset.choice;save();render()});$('#name').value=state.name;$('#name').oninput=e=>{state.name=e.target.value.trim()||'Dagg';save();sidebar()};document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{state.gender=b.dataset.gender;save();render()});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state[b.dataset.key]=b.dataset.color;save();render()})}}
function mouthShape(){const mouths={smile:'<path d="M150 91Q155 97 161 91" fill="none" stroke="#683e36" stroke-width="1.5" stroke-linecap="round"/>',big:'<path d="M149 90H162Q160 101 155 99Q151 98 149 90Z" fill="#653b35"/><path d="M151 91H160L159 94H152Z" fill="#fff9ef"/>',straight:'<path d="M152 93H159" stroke="#683e36" stroke-width="1.6" stroke-linecap="round"/>',surprised:'<ellipse cx="155" cy="94" rx="3" ry="4" fill="#653b35"/>'};return '<g class="fairy-mouth">'+(mouths[state.mouth]||mouths.smile)+'</g>'}
