function soundButton(){const b=$('#soundToggle');if(!b)return;const on=state.sound!==false;b.textContent=on?'🔊':'🔈';b.setAttribute('aria-pressed',on);b.setAttribute('aria-label',on?'Ljud på':'Ljud av')}if($('#soundToggle')){$('#soundToggle').onclick=()=>{state.sound=state.sound===false;save();soundButton();sfx('land')};soundButton()}

// Invite a friend: the phone's own share sheet, or copy the link.
async function inviteFriend(){const say=t=>typeof enLang==='function'&&enLang()&&typeof tr==='function'?tr(t):t;const url=location.origin+location.pathname;try{if(navigator.share){await navigator.share({title:'The Big Frog Race',text:say('Följ med till Älvskogen och tävla med din egen groda!'),url});return}await navigator.clipboard.writeText(url);toast('Länken är kopierad – skicka den till en kompis!')}catch(e){if(e?.name!=='AbortError')toast('Länken till spelet: '+url)}}
if($('#invite'))$('#invite').onclick=inviteFriend;
